                html += `<div class="activity-entry ${sevClass}" data-sev="${sevKey}">`;
                html += `<span class="activity-time">${ts}</span>`;
                html += `<span class="activity-sev">${escapeHtml((alert.severity || 'info').toUpperCase())}</span>`;
